import { assemblyBehind } from "../boundary/assembly/assembly-registry.js";
import { actionNameOf, conceptNameOf } from "../reactions/concepts/introspect.js";
import { wireContracts } from "../boundary/wire/wire-contracts.js";
import { applicationDiagnostics } from "./diagnostics.js";
const INTERNAL_BOUNDARY_ACTIONS = new Set(["register", "cancel", "respondFramework"]);
function publicConceptInventory(concepts) {
    return concepts.map((concept) => concept.name === "RequestBoundary"
        ? {
            ...concept,
            actions: concept.actions.filter(({ name }) => !INTERNAL_BOUNDARY_ACTIONS.has(name)),
        }
        : concept);
}
/** Return design data and field-name-redacted summaries of retained occurrences. */
export function inspectAssembly(assembly) {
    const assembled = assemblyBehind(assembly);
    const redactor = assembled.engine.Action.redactor;
    const app = assembled.engine.exportReactions();
    const concepts = publicConceptInventory(assembled.engine.exportConcepts());
    const wire = wireContracts(app, { contracts: assembled.contracts, inventories: concepts });
    return {
        app,
        concepts,
        readBack: assembled.engine.readBack(),
        inputContracts: assembled.contracts,
        diagnostics: applicationDiagnostics(app, assembled.endpoints, wire),
        occurrences: [...assembled.engine.Action.actions.values()].map(({ concept, action, by, output, outcome }) => ({
            concept: conceptNameOf(concept),
            action: actionNameOf(action),
            ...(by === undefined ? {} : { by }),
            ...(output === undefined
                ? {}
                : { output: redactor.redact(output) }),
            ...(outcome === undefined ? {} : { outcome: redactor.redact(outcome) }),
        })),
    };
}
